########## overrides/app/components/ui-kits/molecules/zimmProductContent/index.tsx
     1	import React from 'react';
     2	import { chakra, useStyleConfig } from '@chakra-ui/react';
     3	import { ZimmProductName } from 'app/components/ui-kits/atoms/zimmProductName';
     4	import { ZimmProductPrice } from 'app/components/ui-kits/atoms/zimmProductPrice';
     5	import { ZimmProductDescription } from 'app/components/ui-kits/atoms/zimmProductDescription';
     6	
     7	const ZIMM_PRODUCT_CONTENT_RECIPE = 'ZimmProductContent';
     8	
     9	type ZimmProductContentProps = {
    10	  /** The product's display name. */
    11	  name: string;
    12	  /**
    13	   * Heading level for the name. Passed through rather than fixed here so the caller keeps
    14	   * control of the page's heading outline — see `ZimmProductName`.
    15	   */
    16	  headingLevel: 'h1' | 'h2' | 'h3';
    17	  /**
    18	   * Price, already formatted for the storefront's locale and currency by the caller. Optional
    19	   * for the same reason as `description`: `ZimmProductPrice` renders nothing when the value is
    20	   * absent or empty, so the group's `gap` collapses to whatever actually rendered.
    21	   */
    22	  price?: string;
    23	  /** Long description as authored in Business Manager. Omitted when the product has none. */
    24	  description?: string;
    25	};
    26	
    27	/**
    28	 * Molecule — the PDP text group: name, price, description.
    29	 *
    30	 * Model copy and the style code are deliberately *not* here. The design places them at the
    31	 * bottom of the column, after the accordions, so the page positions them itself rather than
    32	 * this molecule holding them and then having to unpick the order.
    33	 */
    34	export const ZimmProductContent = ({ name, headingLevel, price, description }: ZimmProductContentProps) => {
    35	  const styles = useStyleConfig(ZIMM_PRODUCT_CONTENT_RECIPE, {});
    36	
    37	  return (
    38	    <chakra.div __css={styles} data-testid="product-content">
    39	      <ZimmProductName name={name} as={headingLevel} />
    40	      <ZimmProductPrice price={price} />
    41	      <ZimmProductDescription description={description} />
    42	    </chakra.div>
    43	  );
    44	};
########## overrides/app/components/ui-kits/atoms/zimmProductPrice/index.tsx
     1	import React from 'react';
     2	import { chakra, useStyleConfig } from '@chakra-ui/react';
     3	
     4	const ZIMM_PRODUCT_PRICE_RECIPE = 'ZimmProductPrice';
     5	
     6	type ZimmProductPriceProps = {
     7	  /**
     8	   * The price, already formatted for the storefront's locale and currency by the caller
     9	   * (`intl.formatNumber` at the page). This atom does no formatting of its own so it stays
    10	   * usable from Storybook without an intl provider.
    11	   *
    12	   * Optional because the page's mapper resolves an absent price to `''` rather than to a
    13	   * formatted `NaN` — see `pages/product-detail/productInfo.ts`'s `selectPdpProductInfo` and
    14	   * the assertion it carries in `productInfo.test.ts`. That empty string reaches this atom
    15	   * unchanged and the decision not to render is taken here.
    16	   */
    17	  price?: string;
    18	  /** Reserved for SFCC-194's was/now treatment; only `default` is implemented today. */
    19	  variant?: 'default';
    20	};
    21	
    22	/**
    23	 * Atom — the single, full product price. Styling lives in `zimmProductPrice.css.ts` and is
    24	 * consumed through the theme, per the one-canonical-styling-surface rule.
    25	 *
    26	 * Renders nothing when there is no price, so a caller can place it unconditionally — the same
    27	 * contract as `ZimmProductDescription`. Rendering an empty `<p>` instead would still take a
    28	 * flex `gap` in `ZimmProductContent`'s column, leaving a hole where the price should be.
    29	 */
    30	export const ZimmProductPrice = ({ price, variant = 'default' }: ZimmProductPriceProps) => {
    31	  // Guard below the hook, never above it: an early return before `useStyleConfig` makes the
    32	  // hook call conditional, which `react-hooks/rules-of-hooks` reports as an error rather than a
    33	  // warning. Same ordering as `ZimmProductDescription` and `ZimmProductStyleCode`.
    34	  const styles = useStyleConfig(ZIMM_PRODUCT_PRICE_RECIPE, { variant });
    35	  if (!price) return null;
    36	
    37	  return (
    38	    <chakra.p __css={styles} textStyle="price" data-testid="product-price">
    39	      {price}
    40	    </chakra.p>
    41	  );
    42	};
########## overrides/app/components/ui-kits/atoms/zimmProductStyleCode/index.tsx
     1	import React from 'react';
     2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
     3	
     4	const ZIMM_PRODUCT_STYLE_CODE_RECIPE = 'ZimmProductStyleCode';
     5	
     6	// Hardcoded UI copy, not a prop and not a CMS lookup — see the note on the component below.
     7	// Named rather than inlined so the string sits at the top of the file, the same way
     8	// zimmSubscribeModal/index.tsx keeps PRIVACY_CONSENT_COPY and ACCESSIBILITY_DISCLAIMER_COPY.
     9	const LABEL = 'Style Code:';
    10	
    11	type ZimmProductStyleCodeProps = {
    12	  /**
    13	   * The master product's style number. This is the style code shown to shoppers, which is not
    14	   * the same value as the variant `product.id`.
    15	   */
    16	  value?: string;
    17	};
    18	
    19	/**
    20	 * Atom — the "Style Code: 7300JS261" line. Renders nothing when no style code is available.
    21	 *
    22	 * The label is the hardcoded LABEL constant above rather than CMS microcopy: useContentful.ts
    23	 * requests entries with no `locale` parameter, so a `uiCopy` lookup would serve the space
    24	 * default to all eight storefronts regardless of site. zimmSubscribeModal/index.tsx hardcodes
    25	 * its copy the same way.
    26	 */
    27	export const ZimmProductStyleCode = ({ value }: ZimmProductStyleCodeProps) => {
    28	  const styles = useMultiStyleConfig(ZIMM_PRODUCT_STYLE_CODE_RECIPE, {});
    29	  if (!value) return null;
    30	
    31	  return (
    32	    <chakra.div __css={styles.root} textStyle="caption" data-testid="product-style-code">
    33	      <chakra.span __css={styles.label}>{LABEL}</chakra.span>
    34	      {/*
    35	        A real space so `textContent` — what a screen reader reads out and what a shopper
    36	        copies — is "Style Code: 8637DS241", matching both composed page designs. It adds no
    37	        visual width: a whitespace-only anonymous flex item is not rendered (CSS Flexbox §4),
    38	        so the 4px `gap` in the recipe remains the only spacing.
    39	      */}{' '}
    40	      <chakra.span __css={styles.value}>{value}</chakra.span>
    41	    </chakra.div>
    42	  );
    43	};
########## overrides/app/components/ui-kits/atoms/zimmProductModelInfo/index.tsx
     1	import React from 'react';
     2	import { chakra, useStyleConfig } from '@chakra-ui/react';
     3	import { isBlankRichText, parseRichText } from 'app/utils/richText';
     4	
     5	const ZIMM_PRODUCT_MODEL_INFO_RECIPE = 'ZimmProductModelInfo';
     6	
     7	type ZimmProductModelInfoProps = {
     8	  /**
     9	   * Model copy from the product's `c_modelFit` attribute. Business Manager authors this as
    10	   * rich text, so it is parsed rather than rendered as a raw string.
    11	   */
    12	  modelInfo?: string;
    13	};
    14	
    15	/**
    16	 * Atom — the model line ("Model is 178cm and wears a size 0"). Renders nothing when
    17	 * `c_modelFit` is absent, which is the common case today.
    18	 *
    19	 * Styling lives in `zimmProductModelInfo.css.ts` and is consumed through the theme, per the
    20	 * one-canonical-styling-surface rule; only the composite `textStyle` stays on the element.
    21	 *
    22	 * A `div`, not a `p`: `parseRichText` can return block-level nodes, and a `<p>` inside a `<p>`
    23	 * is invalid nesting that the browser silently repairs by splitting the element.
    24	 */
    25	export const ZimmProductModelInfo = ({ modelInfo }: ZimmProductModelInfoProps) => {
    26	  // Guard below the hook, never above it — an early return before `useStyleConfig` makes the
    27	  // hook call conditional, which `react-hooks/rules-of-hooks` reports as an error.
    28	  const styles = useStyleConfig(ZIMM_PRODUCT_MODEL_INFO_RECIPE, {});
    29	  if (isBlankRichText(modelInfo)) return null;
    30	  const content = parseRichText(modelInfo);
    31	
    32	  return (
    33	    <chakra.div __css={styles} textStyle="caption" data-testid="product-model-info">
    34	      {content}
    35	    </chakra.div>
    36	  );
    37	};
