     1	import React from 'react';
     2	import { chakra, useStyleConfig } from '@chakra-ui/react';
     3	
     4	const ZIMM_PRODUCT_NAME_RECIPE = 'ZimmProductName';
     5	
     6	type ZimmProductNameProps = {
     7	  /** The product's display name, already resolved by the caller. */
     8	  name: string;
     9	  /**
    10	   * Heading level. Required rather than defaulted: the correct level depends on what else the
    11	   * page has already emitted, and a silent `h1` default duplicates the base PDP's own
    12	   * screen-reader-only `<h1>Product Details</h1>`.
    13	   */
    14	  as: 'h1' | 'h2' | 'h3';
    15	};
    16	
    17	/**
    18	 * Atom — the product name. Styling lives in `zimmProductName.css.ts` and is consumed through
    19	 * the theme, per the one-canonical-styling-surface rule; only the composite `textStyle` stays
    20	 * on the element, since no single CSS custom property expresses it.
    21	 *
    22	 * The element is written as `chakra.p` with an `as` override rather than a fixed heading tag,
    23	 * which is what Chakra's own `Text` did before the recipe landed: the tag is a caller decision
    24	 * and `as` is the only prop that can carry it. `index.stories.tsx` asserts the heading role and
    25	 * level for all three values so this cannot silently degrade to a `<p>`.
    26	 */
    27	export const ZimmProductName = ({ name, as }: ZimmProductNameProps) => {
    28	  const styles = useStyleConfig(ZIMM_PRODUCT_NAME_RECIPE, {});
    29	
    30	  return (
    31	    <chakra.p as={as} __css={styles} textStyle="heading3" data-testid="product-name">
    32	      {name}
    33	    </chakra.p>
    34	  );
    35	};
