100	 * hooks and base components have no compile-time shape. The aliases below name that gap
101	 * once, in one place, instead of spreading bare `any` through the file — narrow them as
102	 * the real shapes are confirmed.
103	 */
104	type SfccProduct = any;
105	type SfccVariant = any;
