109	 * `@salesforce/commerce-sdk-react` types its query/mutation `parameters` more narrowly than
110	 * the base JS page satisfies (it types several always-present values as optional, and takes
111	 * `ids` as an array where the base joins them itself). The casts marked "SDK param widening"
112	 * below exist only to reconcile that; each passes exactly the value the base file passes, so
113	 * none of them changes runtime behaviour.
114	 */
115	
116	/** A basket line item as this page assembles it before handing it to the baskets API. */
117	type BasketLineItem = {
118	  productId?: string;
119	  id?: string;
120	  price?: number;
121	  quantity?: number;
122	  inventoryId?: string;
123	  shipmentId?: string;
124	  bundledProductItems?: Array<{ productId?: string; quantity?: number }>;
125	};
126	
127	/** A child product selection within a product set or bundle. */
128	type ChildProductSelection = {
129	  product?: SfccProduct;
130	  variant?: SfccVariant;
131	  quantity?: number;
132	};
133	
134	/** The imperative handle ProductView exposes for set/bundle child validation. */
135	type ChildProductRef = {
136	  ref: HTMLDivElement | null;
137	  validateOrderability: ProductViewRefScope['validateOrderability'];
138	};
139	
140	/** One row of the array the base ProductView passes to `addToCart`. */
141	type ProductSelectionValue = {
142	  product?: SfccProduct;
143	  variant?: SfccVariant;
144	  quantity?: number;
145	};
146	
147	/**
148	 * Errors thrown by the commerce SDK carry the originating `Response`, which the base
149	 * page reads to map an API status onto an SSR-visible HTTP error.
150	 */
151	type CommerceApiError = Error & { response?: { status?: number } };
152	
153	const ProductDetail = () => {
154	  // react-intl returns an already-bound `formatMessage`, and this destructuring is the base
155	  // file's own shape — the rule cannot see either.
156	  // eslint-disable-next-line @typescript-eslint/unbound-method
157	  const { formatMessage, formatNumber } = useIntl();
158	  const history = useHistory();
159	  const location = useLocation();
160	  const einstein = useEinstein();
161	  const dataCloud = useDataCloud();
162	  const activeData = useActiveData();
163	  const toast = useToast();
164	  const navigate = useNavigation();
165	  const customerId = useCustomerId();
166	  const { onOpen: onOpenStoreLocator } = useStoreLocatorModal();
167	  const multishipEnabled = getConfig()?.app?.multishipEnabled ?? true;
168	  const storeLocatorEnabled = getConfig()?.app?.storeLocatorEnabled ?? STORE_LOCATOR_IS_ENABLED;
169	
170	  /****************************** Basket *********************************/
171	  const { data: basket, isLoading: isBasketLoading } = useCurrentBasket();
172	  const { addItemToNewOrExistingBasket } = useShopperBasketsMutationHelper();
173	  const updateItemsInBasketMutation = useShopperBasketsMutation('updateItemsInBasket');
174	  const { res } = useServerContext();
175	  if (res) {
176	    res.set('Cache-Control', `s-maxage=${MAX_CACHE_AGE}, stale-while-revalidate=${STALE_WHILE_REVALIDATE}`);
177	  }
178	
179	  /*************************** Pick up in Store ********************/
180	  const { selectedStore } = useSelectedStore();
181	  const selectedInventoryId = selectedStore?.inventoryId || null;
182	
183	  const { addInventoryIdsToPickupItems, updateDefaultShipmentIfNeeded, hasPickupItems } = usePickupShipment(basket);
184	
185	  /*************************** Multiship ********************/
186	  const { getShipmentIdForItems } = useMultiship(basket);
187	
188	  /*************************** Product Detail and Category ********************/
189	  const { productId } = useParams<{ productId?: string }>();
190	  const urlParams = new URLSearchParams(location.search);
191	  // SDK param widening: this component only mounts on `/product/:productId`, so one of the
192	  // two is always present. `useParams` types every segment optional by design — see the
193	  // comment on the react-router-dom shim in overrides/app/types/vendor.d.ts.
194	  const requestedProductId = (urlParams.get('pid') || productId) as string;
195	  const {
196	    data: productResponse,
197	    isLoading: isProductLoading,
198	    isError: isProductError,
199	    error: productError,
200	  } = useProduct(
201	    {
202	      parameters: {
203	        id: requestedProductId,
204	        perPricebook: true,
205	        expand: [
206	          'availability',
207	          'promotions',
208	          'options',
209	          'images',
210	          'prices',
211	          'variations',
212	          'set_products',
213	          'bundled_products',
214	          'page_meta_tags',
215	        ],
216	        allImages: true,
217	        ...(selectedInventoryId ? { inventoryIds: selectedInventoryId } : {}),
218	      },
219	    },
220	    {
221	      // When shoppers select a different variant (and the app fetches the new data),
222	      // the old data is still rendered (and not the skeletons).
223	      keepPreviousData: true,
224	    },
225	  );
226	
227	  // Note: Since category needs id from product detail, it can't be server side rendered atm
228	  // until we can do dependent query on server
229	  const {
230	    data: category,
231	    isError: isCategoryError,
232	    error: categoryError,
233	  } = useCategory({
234	    parameters: {
235	      // SDK param widening — `useCategory` is a no-op until the product resolves, exactly as
236	      // in the base file.
237	      id: productResponse?.primaryCategoryId as string,
238	      levels: 1,
239	    },
240	  });
241	
242	  /****************************** Sets and Bundles *********************************/
243	  const [childProductSelection, setChildProductSelection] = useState<Record<string, ChildProductSelection>>({});
244	  const [childProductOrderability, setChildProductOrderability] = useState<Record<string, ChildProductOrderability>>(
245	    {},
246	  );
247	  const [selectedBundleQuantity, setSelectedBundleQuantity] = useState(1);
248	  const childProductRefs = React.useRef<Record<string, ChildProductRef>>({});
249	  // Deviation from the base file: `?.` on `type`. The base reads `productResponse?.type.set`,
250	  // which throws if the API ever returns a product without `type` (the SDK types it optional).

