import React from 'react';
import { ZimmProductContent } from 'app/components/ui-kits/molecules/zimmProductContent';
import { ZimmProductPrice } from 'app/components/ui-kits/atoms/zimmProductPrice';
import { ZimmProductMeta } from 'app/components/ui-kits/molecules/zimmProductMeta';
import { ZimmProductStyleCode } from 'app/components/ui-kits/atoms/zimmProductStyleCode';
import { ZimmProductModelInfo } from 'app/components/ui-kits/atoms/zimmProductModelInfo';
import { selectPdpProductInfo, type PdpProductInfo } from 'app/pages/product-detail/productInfo';

declare const isBundle: boolean;
declare const maybeStr: string | undefined;
const info: PdpProductInfo = { name: 'X', price: '$1', description: undefined, modelInfo: undefined, styleCode: 'S' };

// 1a: literal undefined into the molecule + atom
export const A = () => (
  <>
    <ZimmProductContent name="n" headingLevel="h2" price={undefined} description={undefined} />
    <ZimmProductPrice price={undefined} />
  </>
);

// 1b: string | undefined union
export const B = () => (
  <>
    <ZimmProductContent name="n" headingLevel="h2" price={maybeStr} />
    <ZimmProductPrice price={maybeStr} />
  </>
);

// 1c: the exact ternary from the task premise
export const C = () => (
  <>
    <ZimmProductContent name={info.name} headingLevel="h2" price={isBundle ? undefined : info.price} description={info.description} />
    <ZimmProductPrice price={isBundle ? undefined : info.price} />
  </>
);

// 2: mapper output straight into ZimmProductMeta / the two atoms, incl. the null-able form
const nullable = selectPdpProductInfo({ name: 'n' }, null, 'AUD', (a, c) => `${a}${c}`);
export const D = () => (
  <>
    <ZimmProductMeta modelInfo={info.modelInfo} styleCode={info.styleCode} />
    <ZimmProductMeta modelInfo={nullable?.modelInfo} styleCode={nullable?.styleCode} />
    <ZimmProductModelInfo modelInfo={nullable?.modelInfo} />
    <ZimmProductStyleCode value={nullable?.styleCode} />
    <ZimmProductStyleCode value={undefined} />
  </>
);
EOF
