########## zimmProductContent/index.stories.tsx
     1	import type { Meta, StoryObj } from '@storybook/react-webpack5';
     2	import React from 'react';
     3	import { expect, within } from 'storybook/test';
     4	import { Box } from '@chakra-ui/react';
     5	import { ZimmProductContent } from '.';
     6	
     7	/** The real Shopper Products payload for 8637DS241 (ZimmermannAU, 2026-08-23). */
     8	const REAL_DESCRIPTION = [
     9	  'The Natura Mini Dress in Blue Birds from our Spring 2024 Collection, Natura. ',
    10	  'A long sleeve linen mini dress featuring a deep v-neckline with fitted bodice and full skirt.',
    11	  '<br><ul><li> Linen mini dress</li><li> Long sleeves with fluted cuffs </li>',
    12	  '<li> Crinoline hem </li><li> Invisible zip at centre back</li></ul>',
    13	].join('');
    14	
    15	const meta: Meta<typeof ZimmProductContent> = {
    16	  title: 'Commerce/ZimmProductContent',
    17	  component: ZimmProductContent,
    18	  argTypes: {
    19	    name: { control: 'text' },
    20	    price: { control: 'text' },
    21	    description: { control: 'text' },
    22	    headingLevel: { control: 'inline-radio', options: ['h1', 'h2', 'h3'] },
    23	  },
    24	  decorators: [
    25	    // The DS Content frame is 218px wide inside the info column; showing it at any other
    26	    // width makes the wrap behaviour and the 20px rhythm unreadable.
    27	    (Story: React.ComponentType) => (
    28	      <Box width="218px">
    29	        <Story />
    30	      </Box>
    31	    ),
    32	  ],
    33	};
    34	export default meta;
    35	
    36	type Story = StoryObj<typeof ZimmProductContent>;
    37	
    38	export const Default: Story = {
    39	  args: {
    40	    name: 'Natura Mini Dress',
    41	    headingLevel: 'h1',
    42	    price: '$795.00',
    43	    description: REAL_DESCRIPTION,
    44	  },
    45	};
    46	
    47	export const WithoutDescription: Story = {
    48	  name: 'Without description — rhythm collapses',
    49	  args: {
    50	    name: 'Natura Mini Dress',
    51	    headingLevel: 'h1',
    52	    price: '$795.00',
    53	    description: undefined,
    54	  },
    55	  play: async ({ canvasElement }) => {
    56	    const canvas = within(canvasElement);
    57	    const root = canvas.getByTestId('product-content');
    58	
    59	    // The description atom returns null, so the group must be exactly two rows with no
    60	    // trailing gap. A per-child marginBottom would leave 20px hanging under the price.
    61	    await expect(canvas.queryByTestId('product-description')).not.toBeInTheDocument();
    62	    await expect(root.children).toHaveLength(2);
    63	
    64	    // A flex gap applies only between rendered items, so two children means exactly one gap
    65	    // and no trailing space under the price.
    66	    await expect(getComputedStyle(root).rowGap).toBe('20px');
    67	  },
    68	};
    69	
    70	export const RhythmWithDescription: Story = {
    71	  name: 'Rhythm — 20px between every row',
    72	  args: {
    73	    name: 'Natura Mini Dress',
    74	    headingLevel: 'h1',
    75	    price: '$795.00',
    76	    description: '<p>A long sleeve linen mini dress.</p>',
    77	  },
    78	  play: async ({ canvasElement }) => {
    79	    const root = within(canvasElement).getByTestId('product-content');
    80	    await expect(root.children).toHaveLength(3);
    81	
    82	    // 20px = spacing.l, asserted as a computed value so a change to the token, to the recipe,
    83	    // or to its registration in theme/components/index.ts all surface here rather than only in
    84	    // a visual review. It also pins down that no child can out-specify the container.
    85	    await expect(getComputedStyle(root).rowGap).toBe('20px');
    86	    for (const child of Array.from(root.children)) {
    87	      await expect(getComputedStyle(child).marginTop).toBe('0px');
    88	    }
    89	  },
    90	};
    91	
    92	export const BlankDescription: Story = {
    93	  name: 'Description present but empty — also collapses',
    94	  // Business Manager can save the field as empty markup rather than clearing it, which is not
    95	  // the same input as `undefined` and has to reach the same rendering.
    96	  args: {
    97	    name: 'Natura Mini Dress',
    98	    headingLevel: 'h1',
    99	    price: '$795.00',
   100	    description: '<p></p>',
   101	  },
   102	  play: async ({ canvasElement }) => {
   103	    const canvas = within(canvasElement);
   104	    await expect(canvas.getByTestId('product-content').children).toHaveLength(2);
   105	    await expect(canvas.queryByTestId('product-description')).not.toBeInTheDocument();
   106	  },
   107	};
   108	
   109	export const WithoutPrice: Story = {
   110	  name: 'Price absent — the price row collapses too',
   111	  // Not a hypothetical: the page's mapper resolves a product with no price data to `''` rather
   112	  // than to a formatted NaN, and that empty string reaches ZimmProductPrice unchanged.
   113	  args: {
   114	    name: 'Natura Mini Dress',
   115	    headingLevel: 'h1',
   116	    price: '',
   117	    description: '<p>A long sleeve linen mini dress.</p>',
   118	  },
   119	  play: async ({ canvasElement }) => {
   120	    const canvas = within(canvasElement);
   121	    const root = canvas.getByTestId('product-content');
   122	
   123	    // The middle row is the one that disappears here, so this also pins down that the rhythm
   124	    // is a container `gap` and not a per-child margin — a margin on the name would leave the
   125	    // 20px hanging above a price that is no longer there.
   126	    await expect(canvas.queryByTestId('product-price')).not.toBeInTheDocument();
   127	    await expect(canvas.getByTestId('product-name')).toBeInTheDocument();
   128	    await expect(canvas.getByTestId('product-description')).toBeInTheDocument();
   129	    await expect(getComputedStyle(root).rowGap).toBe('20px');
   130	  },
   131	};
