import React from 'react';
import { describe, test, expect } from 'vitest';
import { render, screen } from '@testing-library/react';
import { isBlankRichText, parseRichText, richTextToPlainText } from 'app/utils/richText';
import { ZimmProductMeta } from 'app/components/ui-kits/molecules/zimmProductMeta';
import { ZimmProductPrice } from 'app/components/ui-kits/atoms/zimmProductPrice';

describe('isBlankRichText across mapper-producible inputs', () => {
  const cases: Array<[string, string | undefined]> = [
    ['undefined', undefined],
    ['empty string', ''],
    ['<p></p>', '<p></p>'],
    ['<p> </p>', '<p> </p>'],
    ['bare <br>', '<br>'],
    ['whitespace only', '   '],
    ['&nbsp;', '&nbsp;'],
    ['<p>&nbsp;</p>', '<p>&nbsp;</p>'],
    ['real copy', '<p>Model is 178cm</p>'],
    ['img only (unwrapped)', '<img src="x">'],
    ['<ul><li></li></ul>', '<ul><li></li></ul>'],
  ];
  for (const [label, input] of cases) {
    test(`isBlankRichText(${label}) -> reported`, () => {
      const blank = isBlankRichText(input);
      const nodes = parseRichText(input);
      console.log(
        `RESULT | ${label.padEnd(22)} | isBlankRichText=${String(blank).padEnd(5)} | nodeCount=${nodes.length} | plain=${JSON.stringify(richTextToPlainText(input))}`,
      );
      expect(typeof blank).toBe('boolean');
    });
  }
});

describe('ZimmProductPrice runtime guard: which values render', () => {
  // `price` is typed string, so these are the JS-reachable strings.
  for (const p of ['', '0', '0.00', '$0.00', ' ', 'NaN', '$NaN'] as string[]) {
    test(`price=${JSON.stringify(p)}`, () => {
      render(<ZimmProductPrice price={p} />);
      const el = screen.queryByTestId('product-price');
      console.log(`PRICE | ${JSON.stringify(p).padEnd(9)} | rendered=${el !== null} | text=${JSON.stringify(el?.textContent ?? null)}`);
      expect(true).toBe(true);
    });
  }
});

describe('ZimmProductMeta guard consistency vs its children', () => {
  const cases: Array<[string, string | undefined, string | undefined]> = [
    ['both absent', undefined, undefined],
    ['both empty-ish', '<p></p>', ''],
    ['styleCode whitespace only', '<p></p>', '   '],
    ['modelInfo whitespace only', '   ', undefined],
    ['styleCode real, model blank', '<p></p>', '8637DS241'],
    ['model real, styleCode absent', '<p>Model is 178cm</p>', undefined],
  ];
  for (const [label, modelInfo, styleCode] of cases) {
    test(label, () => {
      const { container } = render(<ZimmProductMeta modelInfo={modelInfo} styleCode={styleCode} />);
      const root = screen.queryByTestId('product-meta');
      const model = screen.queryByTestId('product-model-info');
      const code = screen.queryByTestId('product-style-code');
      console.log(
        `META | ${label.padEnd(28)} | root=${String(root !== null).padEnd(5)} | model=${String(model !== null).padEnd(5)} | code=${String(code !== null).padEnd(5)} | rootText=${JSON.stringify(root?.textContent ?? null)} | domLen=${container.innerHTML.length}`,
      );
      // The trap: a rendered root whose children all collapsed = empty padded box.
      if (root !== null && model === null && code === null) {
        console.log('  >>> EMPTY PADDED BOX REPRODUCED <<<');
      }
      expect(true).toBe(true);
    });
  }
});
EOF
